"""Generate Roblox-ready Luau registry for all published runtime art."""
import json
from pathlib import Path
source = Path("assets/roblox_runtime_assets.json")
data = json.loads(source.read_text())["assets"]
rows = []
for path, record in sorted(data.items()):
    key = path.removeprefix("assets/").removesuffix(".png").replace("/", ".")
    asset_id = int(record["assetId"])
    if asset_id <= 0:
        raise ValueError("Invalid asset ID")
    rows.append((key, asset_id))
lines = [
    "-- AUTO-GENERATED by scripts/build_runtime_registry.py. Do not edit.",
    "local Registry = {}",
    "local ids = {",
]
for key, asset_id in rows:
    lines.append(f'    ["{key}"] = {asset_id},')
lines += [
    "}",
    "function Registry.get(key)",
    "    local id = ids[key]",
    "    if not id then return nil end",
    '    return "rbxassetid://" .. tostring(id)',
    "end",
    "function Registry.apply(imageLabel, key)",
    "    local uri = Registry.get(key)",
    "    if not uri then imageLabel.Visible = false; return false end",
    "    imageLabel.Image = uri",
    "    imageLabel.Visible = true",
    "    return true",
    "end",
    "return Registry",
    "",
]
Path("src/shared/RuntimeAssetRegistry.lua").write_text("\n".join(lines))
